<script setup lang="ts">
import { computed,onMounted,onBeforeUnmount,ref } from 'vue'
import { useRoute,useRouter,onBeforeRouteLeave } from 'vue-router'
import QRCode from 'qrcode'
import { call,newId,identity,ApiError,errorText,savePending,getPending,clearPending,bootstrap,holdPrivateEntry,takePrivateEntry } from '../lib/api'
import { enumCode,display,type Obj } from '../lib/contract'
const route=useRoute(),router=useRouter(),event=ref<Obj>(),party=ref<Obj>(),qr=ref(''),ticketImage=ref(''),queryLink=ref(''),error=ref(''),message=ref(''),busy=ref(false),unknown=ref(false),accepted=ref(false)
const fields=ref<Obj>({companionCount:0}),reference=ref(''),contact=ref(''),channel=ref('EMAIL'),challenge=ref(''),code=ref(''),proof=ref(''),deviceId=ref(''),pairingCode=ref('')
const page=computed(()=>String(route.name)),eventId=computed(()=>String(route.params.eventId||getPending()?.eventId||'')),fieldNames=['name','phone','email','companionCount']
const names:Record<string,string>={name:'姓名',phone:'手机号',email:'邮箱',companionCount:'随行人数'}
let inFlight:Obj|undefined
let uncertainAction: {op:string;payload:Obj;context:string;accept:(result:any)=>Promise<void>|void}|undefined
async function anonAction(op:string,payload:Obj,accept:(result:any)=>Promise<void>|void){
 if(busy.value||unknown.value)return
 uncertainAction={op,payload,context:identity.clientContextId,accept}
 await performAnon()
}
async function performAnon(){
 if(!uncertainAction)return
 const attempt=uncertainAction;const recovering=unknown.value;busy.value=true;error.value=''
 savePending({operationId:attempt.payload.operationId,action:attempt.op,eventId:eventId.value||undefined,clientContextId:attempt.context})
 try{const result=await call(attempt.op,attempt.payload,attempt.context);clearPending();unknown.value=false;uncertainAction=undefined;await attempt.accept(result)}
 catch(e){unknown.value=recovering||!(e instanceof ApiError)||e.uncertain;error.value=errorText(e);if(!unknown.value){clearPending();uncertainAction=undefined}}
 finally{busy.value=false}
}
async function checkUnknown(){const pending=getPending();if(pending?.action==='SubmitRegistration'){await recoverOriginal();return}if(pending?.action==='MyPartyChange'||pending?.action==='MyPartyCancel'){await recoverChange();return}if(uncertainAction){await performAnon();return}error.value='请联系活动工作人员核对原操作。为防止重复处理，此页面不会重新提交。'}
async function exchange(access:Obj){await call('PartyExchange',{operationId:newId(),queryToken:access.queryToken,...(access.changeToken?{changeToken:access.changeToken}:{})});queryLink.value=location.origin+'/me/party#'+new URLSearchParams({queryToken:access.queryToken,...(access.changeToken?{changeToken:access.changeToken}:{})});holdPrivateEntry(queryLink.value)}
async function loadParty(){party.value=await call('MyParty',{});try{const credential=await call('MyCredential',{});if(credential.ticketToken){qr.value=await QRCode.toDataURL(credential.ticketToken,{width:360,margin:3});ticketImage.value=qr.value}else qr.value=''}catch(e){if(!(e instanceof ApiError)||e.code!=='TICKET_UNAVAILABLE')throw e}}
async function readFragment(){const hash=location.hash.slice(1);if(!hash)return;history.replaceState(null,'',location.pathname);const data=new URLSearchParams(hash);const queryToken=data.get('queryToken'),changeToken=data.get('changeToken');if(queryToken)await exchange({queryToken,...(changeToken?{changeToken}:{})});const did=data.get('deviceId'),pair=data.get('pairingCode');if(did&&pair){deviceId.value=did;pairingCode.value=pair}}
async function recoverOriginal(){const p=getPending();if(!p||p.action!=='SubmitRegistration')return;unknown.value=true;busy.value=true;try{const result=await call('RegistrationResult',{eventId:p.eventId,operationId:p.operationId},p.clientContextId);await exchange(result.access);clearPending();unknown.value=false;await router.push('/me/party')}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function submit(){if(busy.value||unknown.value||!event.value)return;busy.value=true;error.value='';const selected=Object.fromEntries(fieldNames.filter(k=>event.value!.fields[k]?.enabled).filter(k=>fields.value[k]!==''&&fields.value[k]!==undefined).map(k=>[k,k==='companionCount'?Number(fields.value[k]):fields.value[k]]));const payload={operationId:newId(),eventId:eventId.value,fields:selected,acceptedNoticeVersion:event.value.noticeVersion,...(proof.value?{phoneVerificationProof:proof.value}:{})};inFlight=payload;const context=identity.clientContextId;savePending({operationId:payload.operationId,action:'SubmitRegistration',eventId:eventId.value,clientContextId:context});try{const result=await call('SubmitRegistration',payload,context);await exchange(result.access);clearPending();fields.value={};await router.push('/me/party')}catch(e){if(e instanceof ApiError&&!e.uncertain){clearPending()}else unknown.value=true;error.value=errorText(e)}finally{busy.value=false}}
async function smsSend(){await anonAction('SmsStart',{operationId:newId(),eventId:eventId.value,phone:fields.value.phone},r=>{challenge.value=r.challengeId;message.value='验证申请已受理，请留意短信。'})}
async function smsVerify(){await anonAction('SmsVerify',{operationId:newId(),eventId:eventId.value,challengeId:challenge.value,code:code.value},r=>{proof.value=r.verificationProof;message.value='手机号验证完成';code.value=''})}
async function recoverStart(){await anonAction('RecoveryStart',{operationId:newId(),eventId:eventId.value,partyReference:reference.value,channel:channel.value,contact:contact.value},r=>{challenge.value=r.challengeId;message.value='找回申请已受理。如信息匹配，您将收到验证信息。'})}
async function recoverVerify(){await anonAction('RecoveryVerify',{operationId:newId(),challengeId:challenge.value,code:code.value},async r=>{await exchange(r);await router.push('/me/party')})}
async function change(cancel=false){if(!party.value||busy.value||unknown.value)return;if(cancel&&!confirm('确认取消本组报名？入场码将失效。'))return;busy.value=true;error.value='';const action=cancel?'MyPartyCancel':'MyPartyChange';const payload={operationId:newId(),version:party.value.version,...(cancel?{}:{companionCount:Number(fields.value.companionCount)})};savePending({operationId:payload.operationId,action,eventId:party.value.eventId});try{await call(action,payload);clearPending();await loadParty()}catch(e){unknown.value=!(e instanceof ApiError)||e.uncertain;error.value=errorText(e);if(!unknown.value)clearPending()}finally{busy.value=false}}
async function recoverChange(){const p=getPending();if(!p)return;busy.value=true;try{const r=await call('MyOperation',{operationId:p.operationId,action:p.action});if(enumCode(r.status)==='SUCCEEDED'||enumCode(r.status)==='REJECTED'){clearPending();unknown.value=false;message.value='已查到原操作结果，请核对当前报名状态。';await loadParty()}else message.value='原操作仍在处理中，请稍后查询。'}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function claim(){await anonAction('DeviceClaim',{operationId:newId(),deviceId:deviceId.value,pairingCode:pairingCode.value},async d=>{pairingCode.value='';if(enumCode(d.device.mode)==='KIOSK'){if(identity.staff)await call('Logout',{operationId:newId()});await router.push('/terminal/kiosk')}else await router.push('/check/events/'+d.device.eventId+'/scan')})}
async function copyLink(){try{await navigator.clipboard.writeText(queryLink.value);message.value='私密入口已复制，请妥善保存。'}catch{error.value='暂时无法复制，请使用浏览器的复制功能。'}}
onMounted(async()=>{busy.value=true;try{await bootstrap();await readFragment();const p=getPending();if(p){unknown.value=true;if(p.action==='SubmitRegistration'){await recoverOriginal();return}}
 if(page.value==='P01')event.value=await call('PublicEvent',{eventId:eventId.value})
 if(page.value==='P02'){queryLink.value=takePrivateEntry();await loadParty();fields.value.companionCount=party.value?.fields.companionCount||0}
 }catch(e){error.value=errorText(e)}finally{busy.value=false}})
onBeforeUnmount(()=>{fields.value={};proof.value='';code.value='';contact.value='';queryLink.value='';qr.value='';ticketImage.value='';party.value=undefined;inFlight=undefined;uncertainAction=undefined})
onBeforeRouteLeave(()=>!unknown.value)
</script>
<template>
 <main class="public-shell"><div class="public-brand">UniGate</div><section class="center-card participant-card">
  <p v-if="error" class="alert" role="alert">{{error}}</p><p v-if="message" class="notice" role="status">{{message}}</p>
  <section v-if="unknown" class="unknown-panel"><h1>结果待确认</h1><p>请勿重新报名或重复提交。恢复连接后查询原操作，或联系活动工作人员核对。</p><button :disabled="busy" @click="checkUnknown">查询原操作结果</button></section>
  <template v-else-if="page==='P01'"><h1>{{event?.title||'活动报名'}}</h1><template v-if="event"><p class="muted">{{display(event.startsAt)}}</p><p v-if="event.venue">{{event.venue}}</p><p v-if="!event.registrationAvailable" class="notice">当前未开放报名，请联系主办方。</p><form v-else @submit.prevent="submit"><template v-for="key in fieldNames" :key="key"><label v-if="event.fields[key]?.enabled" class="field"><span>{{names[key]}}<span v-if="event.fields[key].required"> *</span></span><input v-model="fields[key]" :type="key==='companionCount'?'number':key==='phone'?'tel':key==='email'?'email':'text'" :required="event.fields[key].required" :min="key==='companionCount'?0:undefined" :step="key==='companionCount'?1:undefined" :maxlength="key==='name'?100:key==='phone'?40:254" :inputmode="key==='companionCount'?'numeric':undefined"></label></template><p v-if="event.fields.companionCount.enabled" class="notice">本人 1 位 + 随行 {{Number(fields.companionCount)||0}} 位，共 {{1+(Number(fields.companionCount)||0)}} 位。</p><div v-if="event.phoneVerificationEnabled&&!proof"><button type="button" class="secondary" :disabled="busy||!fields.phone" @click="smsSend">获取手机验证码</button><div v-if="challenge" class="inline-form"><label class="field"><span>验证码</span><input v-model="code" inputmode="numeric" autocomplete="one-time-code"></label><button type="button" :disabled="busy||!code" @click="smsVerify">验证</button></div></div><div class="privacy-notice">{{event.notice}}</div><label class="check-choice"><input v-model="accepted" type="checkbox" required>我已阅读并同意上述报名告知</label><button class="full" :disabled="busy||!accepted||(event.phoneVerificationEnabled&&!proof)">{{busy?'正在提交…':'提交报名'}}</button></form><RouterLink :to="'/e/'+eventId+'/recover'" class="text-link">已报名？找回本组入口</RouterLink></template></template>
  <template v-else-if="page==='P02'"><h1>我的报名</h1><template v-if="party"><span class="badge">{{display(party.status)}}</span><p>报名参考号：{{party.partyReference}}</p><div class="ticket-qr" v-if="qr"><img :src="qr" alt="本组入场二维码"><h2>请出示此码入场</h2><p>同组人员可以分批入场</p><a class="button secondary" :href="ticketImage" download="UniGate-入场码.png">保存入场码</a></div><div v-else class="notice">{{enumCode(party.status)==='PENDING'?'报名正在审核，通过后可在此领取入场码。':'当前暂无有效入场码，请联系主办方。'}}</div><div class="metric-grid"><div><strong>{{party.approvedSize}}</strong><span>已批准人数</span></div><div><strong>{{party.netAdmitted}}</strong><span>累计入场</span></div><div><strong>{{party.remainingCount}}</strong><span>剩余名额</span></div></div><button v-if="queryLink" class="secondary full" @click="copyLink">复制私密查询入口</button><div v-if="party.canChange" class="card"><label class="field"><span>随行人数</span><input v-model.number="fields.companionCount" type="number" min="0" step="1"></label><button :disabled="busy" @click="change(false)">更新随行人数</button></div><button v-if="party.canCancel" class="quiet danger" :disabled="busy" @click="change(true)">取消报名</button><button class="quiet" :disabled="busy" @click="loadParty">刷新状态</button></template></template>
  <template v-else-if="page==='P03'"><h1>找回本组入口</h1><p class="muted">使用报名参考号及原报名联系方式验证。</p><form v-if="!challenge" @submit.prevent="recoverStart"><label class="field"><span>报名参考号</span><input v-model="reference" required maxlength="50"></label><label class="field"><span>验证方式</span><select v-model="channel"><option value="EMAIL">电子邮件</option><option value="SMS">手机短信</option></select></label><label class="field"><span>{{channel==='EMAIL'?'报名邮箱':'报名手机号'}}</span><input v-model="contact" :type="channel==='EMAIL'?'email':'tel'" required></label><button class="full" :disabled="busy">申请找回</button></form><form v-else @submit.prevent="recoverVerify"><label class="field"><span>验证码</span><input v-model="code" required maxlength="12" autocomplete="one-time-code"></label><button class="full" :disabled="busy">验证并打开报名</button></form><p class="muted">未保留参考号或联系方式？请联系活动工作人员核对。</p></template>
  <template v-else-if="page==='S04'"><h1>领取检票终端</h1><p class="muted">请使用负责人提供的终端领取信息。</p><form @submit.prevent="claim"><label class="field"><span>终端编号</span><input v-model="deviceId" required autocomplete="off"></label><label class="field"><span>领取码</span><input v-model="pairingCode" required type="password" autocomplete="off" minlength="16"></label><button class="full" :disabled="busy">激活终端</button></form></template>
 </section></main>
</template>
